representative_cases.predicted_plantuml:
@startuml
start
if (Normal services available?) then (Yes)
  :Use Normal Mode;
else (No)
  :Switch to Direct Mode;
  if (Multiple channels exist?) then (Yes)
    :Manual channel selection;
  else (No)
  endif
  :Use Push-To-Talk (PTT)\nfor voice transmission;
  if (Device is portable?) then (Yes)
    :Provide battery warnings;
  else (No)
  endif
  :Wait for services;
  if (Normal services resumed?) then (No)
    :Continue Direct Mode;
    repeat
      :Use Push-To-Talk (PTT)\nfor voice transmission;
      if (Device is portable?) then (Yes)
        :Provide battery warnings;
      else (No)
      endif
    repeat while (Normal services resumed?) is (No)
  else (Yes)
    :Provide audible/visual indication\nof resumed services;
    :Return to Normal Mode;
  endif
endif
stop
@enduml
